def write(repo):
    for slug, (heading, detail, source, guide) in CONTEXT.items():
        page = Path(repo) / 'directory' / slug / 'index.html'
        markup = page.read_text()
        markup = re.sub(r'<!-- INDUSTRY_CONTEXT_START -->.*?<!-- INDUSTRY_CONTEXT_END -->', '', markup, flags=re.S)
        block = f'''<!-- INDUSTRY_CONTEXT_START --><section class="profile-copy"><h2>{heading}</h2><p>{detail}</p><p><a href="{source}" rel="noopener noreferrer">Official service information</a> · Checked {'October 13, 2026' if slug in ('pittsburgh-music-academy', 'action-appliance-service', 'ace-lock', 'expert-window-cleaning', 'world-of-rugs', 'global-wordsmiths', 'mathnasium-squirrel-hill', 'pittsburgh-ballet-theatre', 'apex-junk-removal-hauling', 'concept-art-gallery', 'animal-friends-university', 'circa-barbershop-pittsburgh', 'gaynors-school-of-cooking', 'primo-tailoring-pittsburgh', 'debatin-piano-service', 'thornton-company-north-hills') else 'October 12, 2026' if slug in ('squirrel-hill-shoe-repair', 'model-cleaners-upper-st-clair') else 'October 10, 2026'}.</p><p>Featured in our <a href="/news/{guide}/">Pittsburgh industry comparison guide</a>. Inclusion is an editorial selection, not an independent award or a guarantee of service quality.</p></section><!-- INDUSTRY_CONTEXT_END -->'''
        assert '</main>' in markup
        page.write_text(markup.replace('</main>', block + '</main>', 1))
    return len(CONTEXT)
